module uart_transmitter #(parameter CLOCK_FREQ = 50000000, BAUD_RATE = 9600) (  
    input wire clk,  
    input wire reset,  
    input wire start,  
    input wire [7:0] data,  
    output reg tx  
);  
    localparam IDLE = 2'b00, START_BIT = 2'b01, DATA_BITS = 2'b10, STOP_BIT = 2'b11;  
    reg [1:0] state = IDLE;  
    reg [3:0] bit_cnt = 0;  
    reg [15:0] clk_div = 0;  
    localparam CLK_DIV = CLOCK_FREQ / BAUD_RATE;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            tx <= 1;  
            bit_cnt <= 0;  
            clk_div <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    tx <= 1;  
                    if (start) state <= START_BIT;  
                end  
                START_BIT: begin  
                    tx <= 0;  
                    if (clk_div < CLK_DIV-1) clk_div <= clk_div + 1;  
                    else begin  
                        clk_div <= 0;  
                        state <= DATA_BITS;  
                        bit_cnt <= 0;  
                    end  
                end  
                DATA_BITS: begin  
                    tx <= data[bit_cnt];  
                    if (clk_div < CLK_DIV-1) clk_div <= clk_div + 1;  
                    else begin  
                        clk_div <= 0;  
                        if (bit_cnt < 7)  
                            bit_cnt <= bit_cnt + 1;  
                        else  
                            state <= STOP_BIT;  
                    end  
                end  
                STOP_BIT: begin  
                    tx <= 1;  
                    if (clk_div < CLK_DIV-1) clk_div <= clk_div + 1;  
                    else begin  
                        clk_div <= 0;  
                        state <= IDLE;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

