module watchdog_timer (
    input wire clk,
    input wire reset,
    input wire kick,
    output reg timeout
);
    reg [3:0] count; // 4-bit counter to count up to 8

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 4'b0000;
            timeout <= 0;
        end else if (kick) begin
            count <= 4'b0000;
            timeout <= 0;
        end else begin
            if (count < 4'b1000) begin
                count <= count + 1;
            end else begin
                timeout <= 1;
            end
        end
    end
endmodule

