module watchdog_timer #(parameter TIMEOUT = 10) (
    input wire clk,
    input wire reset,
    input wire kick,
    output reg expired
);

reg [3:0] counter;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        counter <= 0;
        expired <= 0;
    end else if (kick) begin
        counter <= 0;
        expired <= 0;
    end else if (counter < TIMEOUT) begin
        counter <= counter + 1;
        expired <= 0;
    end else begin
        expired <= 1;
    end
end

endmodule

