module WatchdogTimer #(parameter TIMEOUT = 10) (  
    input clk,  
    input feed,  
    output reg reset  
);  
    reg [3:0] counter;  

    always @(posedge clk) begin  
        if (feed) begin  
            counter <= 0;  
            reset <= 0;  
        end else if (counter >= TIMEOUT) begin  
            reset <= 1;  
        end else begin  
            counter <= counter + 1;  
            reset <= 0;  
        end  
    end  
endmodule

