module pipelined_processor (
    input clk,
    input rst,
    input [7:0] instruction_in,
    output reg [7:0] result_out
);

    reg [7:0] IF_ID_instruction;
    reg [7:0] ID_EX_instruction;
    reg [7:0] EX_MEM_instruction;
    reg [7:0] MEM_WB_instruction;
    reg [7:0] EX_result;
    reg [7:0] MEM_result;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            IF_ID_instruction <= 8'b0;
            ID_EX_instruction <= 8'b0;
            EX_MEM_instruction <= 8'b0;
            MEM_WB_instruction <= 8'b0;
            result_out <= 8'b0;
        end else begin
            // Stage 1: Instruction Fetch
            IF_ID_instruction <= instruction_in;

            // Stage 2: Instruction Decode
            ID_EX_instruction <= IF_ID_instruction;

            // Stage 3: Execution
            case (ID_EX_instruction[7:6]) // Assuming the top 2 bits define the operation
                2'b00: EX_result <= ID_EX_instruction[5:0] + ID_EX_instruction[5:0]; // ADD
                2'b01: EX_result <= ID_EX_instruction[5:0] - ID_EX_instruction[5:0]; // SUB
                2'b10: EX_result <= ID_EX_instruction[5:0] & ID_EX_instruction[5:0]; // AND
                default: EX_result <= 8'b0;
            endcase
            EX_MEM_instruction <= EX_result;

            // Stage 4: Memory Access
            MEM_result <= EX_MEM_instruction; // Simple pass-through for this example
            MEM_WB_instruction <= MEM_result;

            // Stage 5: Write Back
            result_out <= MEM_WB_instruction;
        end
    end
endmodule

