module PISO (
    input wire clk,
    input wire reset,
    input wire load,
    input wire shift,
    input wire [4:0] parallel_in,
    output reg serial_out
);
    reg [4:0] shift_reg;
    integer count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shift_reg <= 5'b0;
            serial_out <= 1'b0;
            count <= 0;
        end else if (load) begin
            shift_reg <= parallel_in;
            count <= 5; // Load the entire 5-bit input
        end else if (shift && count > 0) begin
            serial_out <= shift_reg[4]; // Output the MSB
            shift_reg <= shift_reg << 1; // Shift left
            count <= count - 1; // Decrease count
        end
    end
endmodule

