module convolutional_encoder (
    input clk,
    input reset,
    input data_in,
    output reg [1:0] encoded_out
);
    reg [2:0] state; // 3-bit state for constraint length of 3

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 3'b000;
            encoded_out <= 2'b00;
        end else begin
            // Update the state: Shift left and insert new data
            state <= {state[1:0], data_in};

            // Calculate the output based on the current state
            encoded_out[0] <= state[0] ^ state[1] ^ state[2]; // G1
            encoded_out[1] <= state[0] ^ state[2];            // G2
        end
    end
endmodule

module rrt_tree #(  
    parameter BOUNDARY_X = 8,  
    parameter BOUNDARY_Y = 8,  
    parameter NUM_POINTS = 5  
) (  
    input clk,  
    input rst,  
    input [7:0] random_x,  
    input [7:0] random_y,  
    output reg [7:0] nearest_x,  
    output reg [7:0] nearest_y  
);  
    reg [7:0] tree_x [0:NUM_POINTS-1];  
    reg [7:0] tree_y [0:NUM_POINTS-1];  
    integer i;  
    integer min_dist;  
    integer curr_dist;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            nearest_x <= 0;  
            nearest_y <= 0;  
            for (i = 0; i < NUM_POINTS; i = i + 1) begin  
                tree_x[i] <= 0;  
                tree_y[i] <= 0;  
            end  
        end else begin  
            // Update tree with new point  
            tree_x[NUM_POINTS-1] <= random_x;  
            tree_y[NUM_POINTS-1] <= random_y;  

            // Find nearest point  
            min_dist = 9999;  
            for (i = 0; i < NUM_POINTS; i = i + 1) begin  
                curr_dist = (tree_x[i] - random_x) * (tree_x[i] - random_x) + (tree_y[i] - random_y) * (tree_y[i] - random_y);  
                if (curr_dist < min_dist) begin  
                    min_dist = curr_dist;  
                    nearest_x <= tree_x[i];  
                    nearest_y <= tree_y[i];  
                end  
            end  
        end  
    end  
endmodule

