module sram_cell (  
    input wire [7:0] data_in,  
    input wire we,  
    input wire re,  
    output reg [7:0] data_out  
);  
    reg [7:0] memory;  

    always @(posedge we or posedge re) begin  
        if (we) begin  
            memory <= data_in;  
        end  
        if (re) begin  
            data_out <= memory;  
        end  
    end  
endmodule

