module ECC_Point_Addition(  
    input [7:0] x1,  
    input [7:0] y1,  
    input [7:0] x2,  
    input [7:0] y2,  
    output reg [7:0] x3,  
    output reg [7:0] y3,  
    input clk,  
    input reset  
);  
    reg [7:0] lambda;  
    reg [7:0] temp_x;  
    reg [7:0] temp_y;  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            x3 <= 8'b0;  
            y3 <= 8'b0;  
        end else begin  
            if (x1 == 8'b0 && y1 == 8'b0) begin  
                // Point at infinity case  
                x3 <= x2;  
                y3 <= y2;  
            end else if (x2 == 8'b0 && y2 == 8'b0) begin  
                x3 <= x1;  
                y3 <= y1;  
            end else if (x1 == x2 && y1 == y2) begin  
                // Doubling case  
                lambda <= (3 * x1 * x1) / (2 * y1);  
                temp_x <= (lambda * lambda) - (2 * x1);  
                temp_y <= lambda * (x1 - temp_x) - y1;  
                x3 <= temp_x;  
                y3 <= temp_y;  
            end else begin  
                // Normal addition case  
                lambda <= (y2 - y1) / (x2 - x1);  
                temp_x <= (lambda * lambda) - x1 - x2;  
                temp_y <= lambda * (x1 - temp_x) - y1;  
                x3 <= temp_x;  
                y3 <= temp_y;  
            end  
        end  
    end  
endmodule

module linked_list_traversal(  
    input clk,  
    input reset,  
    input [7:0] current_data,  
    input [15:0] current_next,  
    output reg [7:0] output_data,  
    output reg done  
);  
    reg [15:0] next_pointer;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            output_data <= 8'd0;  
            done <= 1'b0;  
            next_pointer <= 16'd0;  
        end else begin  
            if (next_pointer == 16'd0) begin  
                output_data <= current_data;  
                next_pointer <= current_next;  
                done <= 1'b0;  
            end else if (next_pointer != 16'd0) begin  
                output_data <= current_data;  
                next_pointer <= current_next;  
                done <= 1'b0;  
            end else begin  
                done <= 1'b1;  
            end  
        end  
    end  
endmodule

